-- Frozen Room schema from the schema-86 release, before reverting it.
CREATE TABLE IF NOT EXISTS `password_entries` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `title` TEXT NOT NULL, `website` TEXT NOT NULL, `username` TEXT NOT NULL, `password` TEXT NOT NULL, `notes` TEXT NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `isFavorite` INTEGER NOT NULL, `sortOrder` INTEGER NOT NULL, `isGroupCover` INTEGER NOT NULL, `appPackageName` TEXT NOT NULL, `appName` TEXT NOT NULL, `email` TEXT NOT NULL, `phone` TEXT NOT NULL, `addressLine` TEXT NOT NULL, `city` TEXT NOT NULL, `state` TEXT NOT NULL, `zipCode` TEXT NOT NULL, `country` TEXT NOT NULL, `creditCardNumber` TEXT NOT NULL, `creditCardHolder` TEXT NOT NULL, `creditCardExpiry` TEXT NOT NULL, `creditCardCVV` TEXT NOT NULL, `categoryId` INTEGER, `boundNoteId` INTEGER DEFAULT NULL, `keepassDatabaseId` INTEGER DEFAULT NULL, `keepassGroupPath` TEXT DEFAULT NULL, `keepass_entry_uuid` TEXT DEFAULT NULL, `keepass_group_uuid` TEXT DEFAULT NULL, `mdbx_database_id` INTEGER DEFAULT NULL, `mdbx_folder_id` TEXT DEFAULT NULL, `authenticatorKey` TEXT NOT NULL, `passkey_bindings` TEXT NOT NULL DEFAULT '', `ssh_key_data` TEXT NOT NULL DEFAULT '', `loginType` TEXT NOT NULL DEFAULT 'PASSWORD', `ssoProvider` TEXT NOT NULL DEFAULT '', `ssoRefEntryId` INTEGER DEFAULT NULL, `wifi_metadata` TEXT NOT NULL DEFAULT '', `customIconType` TEXT NOT NULL DEFAULT 'NONE', `customIconValue` TEXT DEFAULT NULL, `customIconUpdatedAt` INTEGER NOT NULL DEFAULT 0, `isDeleted` INTEGER NOT NULL DEFAULT 0, `deletedAt` INTEGER DEFAULT NULL, `isArchived` INTEGER NOT NULL DEFAULT 0, `archivedAt` INTEGER DEFAULT NULL, `replica_group_id` TEXT DEFAULT NULL, `password_group_id` TEXT DEFAULT NULL, `bitwarden_vault_id` INTEGER DEFAULT NULL, `bitwarden_cipher_id` TEXT DEFAULT NULL, `bitwarden_folder_id` TEXT DEFAULT NULL, `bitwarden_revision_date` TEXT DEFAULT NULL, `bitwarden_cipher_type` INTEGER NOT NULL DEFAULT 1, `bitwarden_local_modified` INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS `index_password_entries_isDeleted` ON `password_entries` (`isDeleted`);
CREATE INDEX IF NOT EXISTS `index_password_entries_isArchived` ON `password_entries` (`isArchived`);
CREATE INDEX IF NOT EXISTS `index_password_entries_replica_group_id` ON `password_entries` (`replica_group_id`);
CREATE INDEX IF NOT EXISTS `index_password_entries_keepass_entry_uuid` ON `password_entries` (`keepass_entry_uuid`);
CREATE INDEX IF NOT EXISTS `index_password_entries_mdbx_database_id` ON `password_entries` (`mdbx_database_id`);
CREATE INDEX IF NOT EXISTS `index_password_entries_mdbx_database_folder` ON `password_entries` (`mdbx_database_id`, `mdbx_folder_id`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_password_entries_bitwarden_vault_cipher_unique` ON `password_entries` (`bitwarden_vault_id`, `bitwarden_cipher_id`);
CREATE TABLE IF NOT EXISTS `secure_items` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `itemType` TEXT NOT NULL, `title` TEXT NOT NULL, `notes` TEXT NOT NULL, `isFavorite` INTEGER NOT NULL, `sortOrder` INTEGER NOT NULL, `createdAt` INTEGER NOT NULL, `updatedAt` INTEGER NOT NULL, `itemData` TEXT NOT NULL, `imagePaths` TEXT NOT NULL, `categoryId` INTEGER DEFAULT NULL, `keepass_database_id` INTEGER DEFAULT NULL, `keepass_group_path` TEXT DEFAULT NULL, `keepass_entry_uuid` TEXT DEFAULT NULL, `keepass_group_uuid` TEXT DEFAULT NULL, `mdbx_database_id` INTEGER DEFAULT NULL, `mdbx_folder_id` TEXT DEFAULT NULL, `isDeleted` INTEGER NOT NULL DEFAULT 0, `deletedAt` INTEGER DEFAULT NULL, `isArchived` INTEGER NOT NULL DEFAULT 0, `archivedAt` INTEGER DEFAULT NULL, `bitwarden_archive_intent` INTEGER DEFAULT NULL, `replica_group_id` TEXT DEFAULT NULL, `bitwarden_vault_id` INTEGER DEFAULT NULL, `bitwarden_cipher_id` TEXT DEFAULT NULL, `bitwarden_folder_id` TEXT DEFAULT NULL, `bitwarden_revision_date` TEXT DEFAULT NULL, `bitwarden_local_modified` INTEGER NOT NULL DEFAULT 0, `sync_status` TEXT NOT NULL DEFAULT 'NONE');
CREATE INDEX IF NOT EXISTS `index_secure_items_isDeleted` ON `secure_items` (`isDeleted`);
CREATE INDEX IF NOT EXISTS `index_secure_items_replica_group_id` ON `secure_items` (`replica_group_id`);
CREATE INDEX IF NOT EXISTS `index_secure_items_keepass_entry_uuid` ON `secure_items` (`keepass_entry_uuid`);
CREATE INDEX IF NOT EXISTS `index_secure_items_mdbx_database_id` ON `secure_items` (`mdbx_database_id`);
CREATE INDEX IF NOT EXISTS `index_secure_items_mdbx_database_folder` ON `secure_items` (`mdbx_database_id`, `mdbx_folder_id`);
CREATE UNIQUE INDEX IF NOT EXISTS `index_secure_items_bitwarden_vault_cipher_unique` ON `secure_items` (`bitwarden_vault_id`, `bitwarden_cipher_id`);
CREATE TABLE IF NOT EXISTS `categories` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `sortOrder` INTEGER NOT NULL, `bitwarden_vault_id` INTEGER DEFAULT NULL, `bitwarden_folder_id` TEXT DEFAULT NULL, `mdbx_database_id` INTEGER DEFAULT NULL, `sync_item_types` TEXT DEFAULT NULL);
CREATE TABLE IF NOT EXISTS `operation_logs` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `itemType` TEXT NOT NULL, `itemId` INTEGER NOT NULL, `itemTitle` TEXT NOT NULL, `operationType` TEXT NOT NULL, `changesJson` TEXT NOT NULL DEFAULT '', `deviceId` TEXT NOT NULL DEFAULT '', `deviceName` TEXT NOT NULL DEFAULT '', `timestamp` INTEGER NOT NULL, `isReverted` INTEGER NOT NULL DEFAULT 0);
