CREATE TABLE IF NOT EXISTS `timeline_version_snapshots` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `operation_log_id` INTEGER NOT NULL, `item_type` TEXT NOT NULL, `item_id` INTEGER NOT NULL, `operation_type` TEXT NOT NULL, `encrypted_changes_json` TEXT NOT NULL, `created_at` INTEGER NOT NULL);
