CREATE INDEX IF NOT EXISTS `index_timeline_events_occurredAt_id` ON `timeline_events` (`occurredAt`, `id`);
CREATE INDEX IF NOT EXISTS `index_timeline_events_parentId` ON `timeline_events` (`parentId`);
CREATE TABLE IF NOT EXISTS `timeline_targets` (`eventId` TEXT NOT NULL, `kind` TEXT NOT NULL, `itemId` INTEGER NOT NULL, `scopeKey` TEXT NOT NULL, PRIMARY KEY(`eventId`, `kind`, `itemId`), FOREIGN KEY(`eventId`) REFERENCES `timeline_events`(`id`) ON UPDATE NO ACTION ON DELETE CASCADE );
CREATE INDEX IF NOT EXISTS `index_timeline_targets_kind_itemId` ON `timeline_targets` (`kind`, `itemId`);
CREATE INDEX IF NOT EXISTS `index_timeline_targets_scopeKey` ON `timeline_targets` (`scopeKey`);
CREATE TABLE IF NOT EXISTS `local_keepass_databases` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `name` TEXT NOT NULL, `filePath` TEXT NOT NULL, `keyFileUri` TEXT, `key_file_internal_path` TEXT, `key_file_name` TEXT, `key_file_fingerprint` TEXT, `storage_location` TEXT NOT NULL, `source_type` TEXT NOT NULL, `source_id` INTEGER, `open_mode` TEXT NOT NULL, `working_copy_path` TEXT, `cache_copy_path` TEXT, `is_offline_available` INTEGER NOT NULL, `encrypted_password` TEXT, `created_at` INTEGER NOT NULL, `last_accessed_at` INTEGER NOT NULL, `last_synced_at` INTEGER, `last_sync_status` TEXT NOT NULL, `last_sync_error` TEXT, `last_sync_state_updated_at` INTEGER NOT NULL, `is_default` INTEGER NOT NULL, `description` TEXT, `entry_count` INTEGER NOT NULL, `sort_order` INTEGER NOT NULL, `kdbx_major_version` INTEGER NOT NULL, `cipher_algorithm` TEXT NOT NULL, `kdf_algorithm` TEXT NOT NULL, `kdf_transform_rounds` INTEGER NOT NULL, `kdf_memory_bytes` INTEGER NOT NULL, `kdf_parallelism` INTEGER NOT NULL);
