CREATE INDEX IF NOT EXISTS `index_local_keepass_databases_key_file_fingerprint` ON `local_keepass_databases` (`key_file_fingerprint`);
CREATE TABLE IF NOT EXISTS `keepass_remote_sources` (`id` INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL, `provider_type` TEXT NOT NULL, `display_name` TEXT NOT NULL, `remote_path` TEXT NOT NULL, `remote_parent_path` TEXT, `base_url` TEXT, `account_id` TEXT, `drive_id` TEXT, `item_id` TEXT, `username_encrypted` TEXT, `password_encrypted` TEXT, `token_ref` TEXT, `allow_metered_network` INTEGER NOT NULL, `auto_sync_enabled` INTEGER NOT NULL, `created_at` INTEGER NOT NULL, `updated_at` INTEGER NOT NULL);
